// TH15 Stage 3 midboss wave 09.
// Entry: st03.ecl.txt:1618-1646 (MainSub05). Dependencies: GirlA03 489-497,
// GirlA03F 499-521, GirlA03_at 523-580, GirlD01 841-865, GirlD01_at 867-913.
// GirlA03_at2 (582-602) is the N/H/L death callback; the invulnerable training
// shell never kills these enemies, so that laser branch is not triggered.

const TH15_STAR_R: int = 608;      // source etSprite(0,16,2)
const TH15_RING_BALL2: int = 464;  // source etSprite(0,7,2)
const BULLET_COLOR: int = 2;

const TIME_LIMIT: int = 2224;      // 120 opening + 2100 window + 4 startup margin
const OPENING_BUFFER: int = 120;

const GIRL_A03_HP: int = 70;
const GIRL_A03_SCORE: int = 1000;
const GIRL_D01_HP: int = 1200;
const GIRL_D01_SCORE: int = 1000;

const START_X: fx = -120fx;   // MainSub05_100: %B = _f(-120)
const LINE_Y: fx = -24fx;
const LINE_STEP: fx = 24fx;
const LINE_COUNT: int = 10;   // $C and $D
const ROUNDS: int = 5;        // $A

// GirlA03_at: wait(60), etSprite(0,16,2), etAim(0,3) 1 way x layers, etAngle(0,ANGLE_PLAYER,0),
// one volley per enemy (diffI($B,1,1,1,1)). Layer speeds are etSpeed(speed0=top, speed1=bottom).
async sub girl_a03_fire() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var speed0: fx = 2.0fx;   // Easy !E 1.2f; !E 2.0f
    var speed1: fx = 1.2fx;
    if rank == 1 {
        speed0 = 2.5fx;       // !N 1.2f; !N 2.5f
    }
    if rank == 2 {
        layers = 3;           // !H 3
        speed0 = 3.5fx;       // !H 1.2f; !H 3.5f
    }
    if rank == 3 {
        layers = 5;           // !LO 5 (Lunatic)
        speed0 = 4.5fx;       // !LO 1.8f; !LO 4.5f
        speed1 = 1.8fx;
    }
    var step: fx = 0fx;
    if layers > 1 {
        step = (speed1 - speed0) / (layers - 1);
    }
    // etAim(0,3) fixed-direction ring, count 1, layers as above; sh_aim reproduces
    // alpha = ANGLE_PLAYER sampled at fire time.
    sh_reset(0);
    sh_sprite(0, TH15_STAR_R, BULLET_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, 1, layers);
    sh_angle(0, 0deg, 0deg);
    sh_speed(0, speed0, step);
    sh_fire(0);
}

async sub girl_a03() {
    set_invuln(65535);
    set_hurtbox(12fx);   // setHurtbox(24,24): ordinary circle takes first value * 0.5
    set_hitbox(8fx);     // setHitbox(16,16)
    // GirlA03F: getAngle(%F2, FINAL_X, FINAL_Y, 0.0f, 448.0f); moveVel(pi/2, 1);
    // moveVelTime(60, 0, %F2, 2.0f).
    var dive: angle = atan2(448fx - $self_y, 0fx - $self_x);
    // enmCreateM gives the child mirror=1 and ordinary velocity writes are x-reflected;
    // the target has no mirror flag, so the reflected target angle is written directly.
    dive = 180deg - dive;
    move_vel(0, 90deg, 1fx, EASE_LINEAR);
    move_vel(60, dive, 2fx, EASE_LINEAR);
    spawn girl_a03_fire();
    wait(120);
    // moveSetMirror(0) is presentation only; moveVel(-999999.0f, 2.0f) keeps the heading.
    move_vel(0, $self_angle, 2fx, EASE_LINEAR);
    // moveVelTime(60, 0, %ANGLE_PLAYER, 1.0f): angle sampled once at this frame.
    var aim: angle = aim_player();
    move_vel(60, aim, 1fx, EASE_LINEAR);
    loop { wait(1000); }
}

// GirlD01_at: wait(60), etSprite(0,7,2), etAim(0,9) modes 9, etCount(count,17),
// etAngle(0,0,0.02617994f), etSpeed(top,1.8f). Mode 9 is the alternating-layer ring,
// so every bullet is fired explicitly with layers outer and ways inner.
async sub girl_d01_fire() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var volleys: int = 6;    // diffI($A, 2, 4, 6, 6)
    if rank == 0 {
        volleys = 2;
    } else if rank == 1 {
        volleys = 4;
    }
    var gap: int = 90;       // wait([-1]): H/L 90
    if rank <= 1 {
        gap = 125;           // E/N 125
    }
    var ways: int = 10;      // etCount(0, [-1], 17): E 5, N/H/L 10
    if rank == 0 {
        ways = 5;
    }
    var speed0: fx = 3.5fx;  // etSpeed(0, [-1.0f], 1.8f)
    if rank == 0 || rank == 1 {
        speed0 = 2.6fx;
    }
    if rank == 2 {
        speed0 = 3.2fx;
    }
    var layers: int = 17;
    var delta: int = 273;    // 0.02617994 rad
    // One ring shot per layer keeps the same 10(i x 65536)/N grid and per-layer speed.
    // Odd layers are the mirrored ring -(R(i)+H); written as base -H with the ring's
    // forward R(i), the point set matches within 1 BAM (creation order not consumed).
    sh_reset(0);
    sh_sprite(0, TH15_RING_BALL2, BULLET_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, ways, 1);
    for v in 0..volleys {
        for q in 0..layers {
            var h: int = ((q + 1) / 2) * delta;
            var k: int = q + (q % 2);            // (q+1) & ~1 with odd layer count
            var speed: fx = speed0 + (1.8fx - speed0) * k / 16fx;
            var off: int = h;
            if q % 2 != 0 {
                off = 0 - h;
            }
            sh_angle(0, off as angle, 0deg);
            sh_speed(0, speed, 0fx);
            sh_fire(0);
        }
        wait(gap);
    }
}

async sub girl_d01() {
    set_invuln(65535);
    set_hurtbox(16fx);   // setHurtbox(32,32)
    set_hitbox(12fx);    // setHitbox(24,24)
    move_vel(0, 90deg, 2.5fx, EASE_LINEAR);
    move_vel(70, 90deg, 0fx, EASE_QUAD_IN);   // moveVelTime(70, 1, pi/2, 0.0f)
    spawn girl_d01_fire();
    wait(80);
    move_speed(120, 0.2fx, EASE_QUAD_IN);     // moveSpeedTime(120, 1, 0.2f)
    wait(400);
    move_speed(120, 3.0fx, EASE_QUAD_IN);     // moveSpeedTime(120, 1, 3.0f)
    loop { wait(1000); }
}

// MainSub05 schedule: five rounds of 10 + 10 GirlA03 at 10-frame spacing, then two GirlD01.
async sub pattern() {
    wait(OPENING_BUFFER);
    for r in 0..ROUNDS {
        var b: fx = START_X;
        for i in 0..LINE_COUNT {
            _ = spawn_enemy(b, LINE_Y, GIRL_A03_HP, 0, GIRL_A03_SCORE, 0, girl_a03);
            b = b + LINE_STEP;
            wait(10);
        }
        for j in 0..LINE_COUNT {
            _ = spawn_enemy(b, LINE_Y, GIRL_A03_HP, 0, GIRL_A03_SCORE, 0, girl_a03);
            b = b - LINE_STEP;
            wait(10);
        }
    }
    _ = spawn_enemy(32fx, LINE_Y, GIRL_D01_HP, 0, GIRL_D01_SCORE, 0, girl_d01);
    _ = spawn_enemy(-32fx, LINE_Y, GIRL_D01_HP, 0, GIRL_D01_SCORE, 0, girl_d01);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
